import sys
import xml.etree.ElementTree as ET
import subprocess

def evaluate_condition(condition):
    try:
        return eval(condition)
    except:
        return 0

def run_command(command):
    result = subprocess.run(command, shell=True, check=False, text=True, capture_output=True)
    output = result.stdout.strip()
    return result.returncode, output

def main():
    if len(sys.argv) != 2:
        print("Usage: runner.py <path-to-xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except Exception as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    for step in root.findall('step'):
        condition = step.get('condition')
        command = step.get('command')
        if not condition or not command:
            continue

        value = evaluate_condition(condition)
        if value <= 0:
            print(f"{step.get('name')}: skipped")
            continue

        exit_code, output = run_command(command)
        if exit_code != 0:
            print(f"{step.get('name')}: failed with exit code {exit_code}")
            sys.exit(exit_code)
        else:
            print(f"{step.get('name')}: {output}")

if __name__ == "__main__":
    main()

