    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except Exception as e:
        print(f"Error parsing XML: {e}", file=sys.stderr)
        sys.exit(1)

    for step in root.findall('step'):
        name = step.get('name')
        condition_str = step.get('condition')
        command_str = step.get('command')

        try:
            value = evaluate_condition(condition_str)
        except Exception as e:
            print(f"{name}: failed with exit code 1 (invalid condition)", file=sys.stderr)
            sys.exit(1)

        if value > 0:
            try:
                result = subprocess.run(command_str, shell=True, check=True, text=True, capture_output=True)
                stdout = result.stdout.strip()
                print(f"{name}: {stdout}")
            except subprocess.CalledProcessError as e:
                print(f"{name}: failed with exit code {e.returncode}")
                sys.exit(e.returncode)
        else:
            print(f"{name}: skipped")

def evaluate_condition(condition_str):
    try:
        # Replace division with integer division operator
        condition_str = condition_str.replace('/', '//')
        # Evaluate the expression
        return eval(condition_str)
    except Exception:
        raise ValueError("Invalid condition expression")

